#[test]
fn admission_refuses_beyond_the_job_queue_bound() {
    let root = bundle();
    for index in 0..=JOB_QUEUE_LIMIT {
        install(root.path(), "rgba", &format!("art/{index}.png"));
    }
    let mut store = store(root.path());
    for index in 0..JOB_QUEUE_LIMIT {
        store.request_png(&format!("art/{index}.png")).unwrap();
    }
    let error = store
        .request_png(&format!("art/{JOB_QUEUE_LIMIT}.png"))
        .unwrap_err();
    assert_eq!(error.code, AssetErrorCode::Limit, "{error}");
    assert_eq!(store.pending_jobs(), JOB_QUEUE_LIMIT);
    assert_eq!(store.counters().admitted, JOB_QUEUE_LIMIT as u64);

    // Draining the queue makes room again without a new store.
    assert!(store.drain(WATCHDOG));
    assert_eq!(store.counters().completed, JOB_QUEUE_LIMIT as u64);
    store
        .request_png(&format!("art/{JOB_QUEUE_LIMIT}.png"))
        .unwrap();
}

#[test]
fn admission_refuses_beyond_the_registry_bound_until_a_slot_is_released() {
    let root = bundle();
    for index in 0..=IMAGE_REGISTRY_LIMIT {
        install(root.path(), "rgba", &format!("art/{index}.png"));
    }
    let mut store = store(root.path());
    let mut resident = Vec::new();
    for index in 0..IMAGE_REGISTRY_LIMIT {
        resident.push(store.request_png(&format!("art/{index}.png")).unwrap());
        if store.pending_jobs() == JOB_QUEUE_LIMIT {
            assert!(store.drain(WATCHDOG));
        }
    }
    assert!(store.drain(WATCHDOG));
    let error = store
        .request_png(&format!("art/{IMAGE_REGISTRY_LIMIT}.png"))
        .unwrap_err();
    assert_eq!(error.code, AssetErrorCode::Limit, "{error}");

    // An unloaded entry keeps its slot until the host drains the transition.
    assert!(store.unload(resident[0]));
    assert!(
        store
            .request_png(&format!("art/{IMAGE_REGISTRY_LIMIT}.png"))
            .is_err()
    );
    store.take_settled();
    store
        .request_png(&format!("art/{IMAGE_REGISTRY_LIMIT}.png"))
        .unwrap();
}

// ---- staged processing -------------------------------------------------

#[test]
fn loading_is_staged_across_bounded_passes_and_yields_identical_pixels() {
    let root = bundle();
    fs::copy(kenney(), root.path().join("sheet.png")).unwrap();
    let reference = {
        let mut store = store(root.path());
        load(&mut store, "sheet.png")
    };
    assert_eq!(reference.len(), 784 * 352 * 4);

    let mut store = store(root.path());
    let id = store.request_png("sheet.png").unwrap();
    let mut previous = store.counters();
    let mut stages = vec![store.status(id).unwrap().stage];
    let mut passes = 0;
    while store.status(id).unwrap().state != ImageState::Ready {
        store.advance(WATCHDOG);
        passes += 1;
        assert!(passes < 200, "loading did not converge");
        let now = store.counters();
        // One pass moves at most the frozen grant, whatever the file size.
        assert!(
            now.bytes_read - previous.bytes_read <= (QUANTA_PER_PASS * WORK_QUANTUM) as u64,
            "pass {passes} read too much"
        );
        assert!(
            now.decode_bands - previous.decode_bands <= QUANTA_PER_PASS as u64,
            "pass {passes} decoded too many bands"
        );
        assert!(store.staged_bytes() <= ENCODED_STAGING_LIMIT);
        previous = now;
        let status = store.status(id).unwrap();
        if stages.last() != Some(&status.stage) {
            stages.push(status.stage);
        }
    }
    // Genuinely staged: the file cannot arrive in a single pass. One pass each
    // for start, read, header, allocate and reader construction, then the
    // conversion passes and the one that observes completion. A pass is bounded
    // by both the eight-band grant and the soft time cutoff, so the count lies
    // between eight bands per pass and one, and is not a fixed number.
    let bands = 36_usize;
    assert!(
        (5 + bands.div_ceil(QUANTA_PER_PASS) + 1..=5 + bands + 2).contains(&passes),
        "{passes} passes"
    );
    assert_eq!(
        stages,
        vec![
            LoadStage::Waiting,
            LoadStage::Read,
            LoadStage::Header,
            LoadStage::Allocate,
            LoadStage::Decode,
            LoadStage::Complete,
        ]
    );
    assert_eq!(store.image(id).unwrap().rgba(), reference);
    assert_eq!(store.counters().bytes_read, 17_497);
    assert_eq!(store.counters().decode_bands, 36);
    assert_eq!(store.staged_bytes(), 0);
    assert_eq!(store.resident_bytes(), reference.len());
}

#[test]
fn admitted_jobs_run_one_at_a_time_in_admission_order() {
    let root = bundle();
    for index in 0..JOB_QUEUE_LIMIT {
        install(root.path(), "interlaced", &format!("art/{index}.png"));
    }
    let mut store = store(root.path());
    let ids: Vec<_> = (0..JOB_QUEUE_LIMIT)
        .map(|index| store.request_png(&format!("art/{index}.png")).unwrap())
        .collect();

    let mut completed = Vec::new();
    let mut passes = 0;
    while completed.len() < ids.len() {
        store.advance(WATCHDOG);
        passes += 1;
        assert!(passes < 500, "queue did not drain");
        // Exactly one job may hold worker resources at a time.
        let loading = ids
            .iter()
            .filter(|id| {
                store
                    .status(**id)
                    .is_some_and(|status| status.state == ImageState::Loading)
            })
            .count();
        assert!(loading <= 1, "{loading} jobs were active at once");
        completed.extend(
            store
                .take_settled()
                .into_iter()
                .map(|status| (status.id, status.state)),
        );
    }
    assert_eq!(
        completed,
        ids.iter()
            .map(|id| (*id, ImageState::Ready))
            .collect::<Vec<_>>()
    );
    assert_eq!(store.pending_jobs(), 0);
}

