#[test]
fn shutdown_cancels_outstanding_work_and_joins_the_worker() {
    let root = bundle();
    fs::copy(kenney(), root.path().join("sheet.png")).unwrap();
    install(root.path(), "rgba", "small.png");
    let mut store = store(root.path());
    let ready = store.request_png("small.png").unwrap();
    assert!(store.drain(WATCHDOG));
    let pinned = store.image(ready).unwrap();
    let loading = store.request_png("sheet.png").unwrap();
    store.advance(WATCHDOG);
    store.advance(WATCHDOG);

    let started = Instant::now();
    store.shutdown();
    assert!(started.elapsed() < WATCHDOG, "worker join stalled");
    assert!(store.status(ready).is_none());
    assert!(store.status(loading).is_none());
    assert_eq!(store.pending_jobs(), 0);
    assert_eq!(store.staged_bytes(), 0);
    // The retained owner still holds valid pixels after the session ends.
    assert_eq!(pinned.rgba(), expected("rgba"));
    assert_eq!(store.resident_bytes(), pinned.rgba().len());
    // Idempotent, and requests are refused afterwards.
    store.shutdown();
    assert_eq!(
        store.request_png("small.png").unwrap_err().code,
        AssetErrorCode::Path
    );
    drop(pinned);
}

/// Tearing a store down mid-load must release what the cancelled job reserved.
/// Retained storage is shared with published and pinned content, so no blanket
/// reset can do this; only the job's own bytes may be dropped.
#[test]
fn shutdown_releases_the_reservations_of_a_cancelled_job() {
    let root = bundle();
    fs::copy(kenney(), root.path().join("sheet.png")).unwrap();
    let mut interrupted_after_reserving = 0;
    for passes in 0..12 {
        let mut store = store(root.path());
        let id = store.request_png("sheet.png").unwrap();
        for _ in 0..passes {
            store.advance(WATCHDOG);
        }
        if store.status(id).unwrap().state != ImageState::Ready && store.resident_bytes() > 0 {
            interrupted_after_reserving += 1;
        }
        store.shutdown();
        // Nothing published and nothing pinned, so every counter returns to zero.
        assert_eq!(store.resident_bytes(), 0, "passes={passes}");
        assert_eq!(store.staged_bytes(), 0, "passes={passes}");
        assert_eq!(store.scratch_bytes(), 0, "passes={passes}");
    }
    // The output reservation is taken a pass before the image can be published,
    // so a run that never observed it would prove nothing.
    assert!(
        interrupted_after_reserving > 0,
        "no shutdown interrupted a job that had already reserved its output"
    );
}

#[test]
fn dropping_a_store_mid_load_terminates_its_worker() {
    let root = bundle();
    fs::copy(kenney(), root.path().join("sheet.png")).unwrap();
    let started = Instant::now();
    for _ in 0..8 {
        let mut store = store(root.path());
        store.request_png("sheet.png").unwrap();
        store.advance(WATCHDOG);
        drop(store);
    }
    assert!(started.elapsed() < WATCHDOG, "worker teardown stalled");
}

// ---- large fixtures ----------------------------------------------------

/// Build the incompressible maximum-size fixture once per test that needs it.
/// Roughly 16.8 MB on disk and 16 MiB of decoded output.
fn maximum_image() -> (Vec<u8>, Vec<u8>) {
    let size = DIMENSION_LIMIT as usize;
    let pixels = png::noise(size, size);
    let encoded = png::rgba(&pixels, size, size);
    (pixels, encoded)
}

#[test]
fn the_encoded_cap_admits_exactly_seventeen_mebibytes_and_probes_one_further_byte() {
    let root = bundle();
    let (pixels, encoded) = maximum_image();
    assert_eq!(pixels.len(), IMAGE_RGBA_LIMIT);
    // The encoded form of a maximum image can exceed its decoded size, which
    // is exactly why the encoded cap carries headroom above 16 MiB.
    assert!(
        encoded.len() > IMAGE_RGBA_LIMIT && encoded.len() < ENCODED_IMAGE_LIMIT,
        "encoded {} bytes",
        encoded.len()
    );
    // Stated exactly so the recorded headroom figure stays checkable: 2048 rows
    // of a filter byte and 8192 pixel bytes, in 257 stored DEFLATE blocks, plus
    // zlib and chunk framing. Phase 0's independently encoded fixture reached
    // the same size, since incompressible input also lands in stored blocks.
    assert_eq!(encoded.len(), 16_780_612);
    fs::write(root.path().join("large.png"), &encoded).unwrap();

    // Padding after IEND keeps the pixels valid, so exactly the cap still
    // decodes while one more byte is refused.
    let mut at_limit = encoded.clone();
    at_limit.resize(ENCODED_IMAGE_LIMIT, 0);
    fs::write(root.path().join("at-limit.png"), &at_limit).unwrap();
    at_limit.push(0);
    fs::write(root.path().join("over-limit.png"), &at_limit).unwrap();

    let mut store = store(root.path());
    assert_eq!(load(&mut store, "large.png"), pixels);
    assert_eq!(store.counters().bytes_read, encoded.len() as u64);

    let before = store.counters();
    let at = store.request_png("at-limit.png").unwrap();
    assert!(store.drain(WATCHDOG));
    let status = store.status(at).unwrap();
    assert_eq!(status.state, ImageState::Ready);
    // Exactly the cap was read and accepted, so the bound is decided by the
    // bytes that actually arrived rather than by the metadata alone.
    assert_eq!(status.bytes_read, ENCODED_IMAGE_LIMIT);
    assert_eq!(store.image(at).unwrap().rgba(), pixels);
    let calls = store.counters().read_calls - before.read_calls;
    // 544 whole quanta, then at least the one-byte overflow probe at EOF.
    assert!(
        calls >= (ENCODED_IMAGE_LIMIT / WORK_QUANTUM + 1) as u64,
        "{calls} read calls"
    );

    let before = store.counters();
    let over = store.request_png("over-limit.png").unwrap();
    assert!(store.drain(WATCHDOG));
    let status = store.status(over).unwrap();
    assert_eq!(status.state, ImageState::Failed);
    assert_eq!(status.error.unwrap().code, AssetErrorCode::Limit);
    // Refused from the early metadata check, before any content was read.
    assert_eq!(store.counters().read_calls, before.read_calls);
    assert_eq!(store.staged_bytes(), 0);
}

/// The early metadata refusal cannot prove that the cap is decided by bytes
/// that actually arrived, because it rejects an oversized file before the first
/// read. Growing the file after its metadata has already been accepted is the
/// only way the read-based check and its one-byte overflow probe can fire, and
/// it is the case that check exists for.
#[test]
fn a_file_that_grows_after_its_metadata_check_is_refused_by_the_reads() {
    let root = bundle();
    let (_, encoded) = maximum_image();
    let mut at_limit = encoded;
    at_limit.resize(ENCODED_IMAGE_LIMIT, 0);
    let path = root.path().join("growing.png");
    fs::write(&path, &at_limit).unwrap();

    let mut store = store(root.path());
    let id = store.request_png("growing.png").unwrap();
    // Two passes open the file and dispatch its first read grant, so the
    // worker's metadata check has already accepted exactly the cap. Only a
    // quantum of a 17 MiB file has been read, so the appended byte lands far
    // ahead of the reader.
    store.advance(WATCHDOG);
    store.advance(WATCHDOG);
    assert_eq!(store.status(id).unwrap().state, ImageState::Loading);
    fs::OpenOptions::new()
        .append(true)
        .open(&path)
        .unwrap()
        .write_all(&[0])
        .unwrap();

    assert!(store.drain(WATCHDOG));
    let status = store.status(id).unwrap();
    assert_eq!(status.state, ImageState::Failed);
    assert_eq!(status.error.unwrap().code, AssetErrorCode::Limit);
    // The probe read exactly one byte past the cap and refused there, rather
    // than reading whatever else the file had grown to hold.
    assert_eq!(status.bytes_read, ENCODED_IMAGE_LIMIT + 1);
    assert_eq!(store.staged_bytes(), 0);
    assert_eq!(store.resident_bytes(), 0);
    assert!(store.service_fault().is_none());
}

#[test]
fn two_maximum_files_load_within_the_aggregate_staging_allowance() {
    let root = bundle();
    let (pixels, encoded) = maximum_image();
    fs::write(root.path().join("a.png"), &encoded).unwrap();
    fs::write(root.path().join("b.png"), &encoded).unwrap();
    assert!(encoded.len() * 2 < ENCODED_STAGING_LIMIT);

    let mut store = store(root.path());
    let a = store.request_png("a.png").unwrap();
    let b = store.request_png("b.png").unwrap();
    // Distinct files with identical bytes are distinct images.
    assert_ne!(a, b);

    let mut peak = 0;
    let mut passes = 0;
    while store.pending_jobs() > 0 {
        store.advance(WATCHDOG);
        passes += 1;
        assert!(passes < 5_000, "aggregate load did not converge");
        peak = peak.max(store.staged_bytes());
        assert!(store.staged_bytes() <= ENCODED_STAGING_LIMIT);
    }
    assert_eq!(store.image(a).unwrap().rgba(), pixels);
    assert_eq!(store.image(b).unwrap().rgba(), pixels);
    assert_eq!(store.resident_bytes(), 2 * IMAGE_RGBA_LIMIT);
    // One job reads at a time, so staging peaks near a single encoded file.
    assert!(
        peak <= ENCODED_IMAGE_LIMIT + QUANTA_PER_PASS * WORK_QUANTUM,
        "peak staging {peak}"
    );
    assert_eq!(store.staged_bytes(), 0);
}

#[test]
fn retained_storage_pressure_fails_a_job_as_capacity() {
    let root = bundle();
    let (_, encoded) = maximum_image();
    let count = STORE_RGBA_LIMIT / IMAGE_RGBA_LIMIT;
    fs::write(root.path().join("0.png"), &encoded).unwrap();
    for index in 1..=count {
        fs::copy(
            root.path().join("0.png"),
            root.path().join(format!("{index}.png")),
        )
        .unwrap();
    }

    let mut store = store(root.path());
    for index in 0..count {
        let id = store.request_png(&format!("{index}.png")).unwrap();
        assert!(store.drain(WATCHDOG));
        assert_eq!(
            store.status(id).unwrap().state,
            ImageState::Ready,
            "image {index}"
        );
    }
    assert_eq!(store.resident_bytes(), STORE_RGBA_LIMIT);

    // The store is full: the next job fails as capacity rather than stalling.
    let refused = store.request_png(&format!("{count}.png")).unwrap();
    assert!(store.drain(WATCHDOG));
    let status = store.status(refused).unwrap();
    assert_eq!(status.state, ImageState::Failed);
    assert_eq!(status.error.unwrap().code, AssetErrorCode::Capacity);
    // Its dimensions were validated before allocation was refused.
    assert_eq!(
        (status.width, status.height),
        (Some(DIMENSION_LIMIT), Some(DIMENSION_LIMIT))
    );
    assert_eq!(store.resident_bytes(), STORE_RGBA_LIMIT);
    assert!(store.service_fault().is_none());

    // Releasing one image makes room for the retry.
    let first = store.take_settled()[0].id;
    assert!(store.unload(first));
    store.service();
    assert_eq!(store.resident_bytes(), STORE_RGBA_LIMIT - IMAGE_RGBA_LIMIT);
    let retry = store.request_png(&format!("{count}.png")).unwrap();
    assert!(store.drain(WATCHDOG));
    assert_eq!(store.status(retry).unwrap().state, ImageState::Ready);
}

// ---- status snapshots --------------------------------------------------

#[test]
fn status_snapshots_are_owned_and_survive_later_service_passes() {
    let root = bundle();
    install(root.path(), "rgba", "art/tiles.png");
    let mut store = store(root.path());
    let id = store.request_png("art/tiles.png").unwrap();
    let queued: ImageStatus = store.status(id).unwrap();
    assert_eq!(queued.state, ImageState::Queued);
    assert_eq!(queued.stage, LoadStage::Waiting);
    assert_eq!(queued.bytes_read, 0);
    assert_eq!(queued.width, None);

    assert!(store.drain(WATCHDOG));
    // The earlier snapshot is a copy, not a view onto the store.
    assert_eq!(queued.state, ImageState::Queued);
    assert_eq!(store.status(id).unwrap().state, ImageState::Ready);
    let retained: ImageId = queued.id;
    assert!(store.status(retained).is_some());
}

// ---- process-bounded decoder probes -------------------------------------

/// Decoder work runs to completion inside non-preemptible stages, and a store
/// joins its worker on drop, so neither `drain`'s deadline nor an unwinding
/// assertion can bound a decoder that never returns. Run the adversarial
/// fixtures in child processes, as `scripting_feasibility` does for the VM, so a
/// regression fails in ten seconds instead of hanging Cargo. The in-process
/// tests above keep their own assertions; what these add is the outer bound.
#[test]
fn adversarial_decoder_fixtures_stay_inside_a_process_watchdog() {
    for probe in [
        "truncated",
        "corrupt",
        "wrong_format",
        "sixteen_bit",
        "apng",
        "huge_dimensions",
        "interlaced",
        "maximum",
        "maximum_drop",
    ] {
        let mut child = Command::new(std::env::current_exe().unwrap())
            .args(["--exact", "isolated_probe", "--nocapture"])
            .env("PROTOGINE_ASSET_PROBE", probe)
            .stdout(std::process::Stdio::null())
            .spawn()
            .unwrap();
        let deadline = Instant::now() + WATCHDOG;
        loop {
            if let Some(status) = child.try_wait().unwrap() {
                assert!(status.success(), "{probe}: {status}");
                break;
            }
            if Instant::now() >= deadline {
                child.kill().unwrap();
                child.wait().unwrap();
                panic!("{probe} exceeded the 10-second process timeout");
            }
            thread::sleep(Duration::from_millis(10));
        }
    }
}

#[test]
fn isolated_probe() {
    let Ok(probe) = std::env::var("PROTOGINE_ASSET_PROBE") else {
        return;
    };
    let root = bundle();
    // The two full decodes are here because of the stages they run, not because
    // their pixels need rechecking: the eagerly decoded Adam7 frame, and a
    // maximum image whose allocation and conversion are the largest this
    // milestone accepts. The rest are refusals reached through the decoder.
    let refusal = match probe.as_str() {
        "truncated" | "corrupt" | "wrong_format" => Some(AssetErrorCode::Format),
        "sixteen_bit" | "apng" => Some(AssetErrorCode::Unsupported),
        "huge_dimensions" => Some(AssetErrorCode::Limit),
        "interlaced" => None,
        "maximum" | "maximum_drop" => {
            let (pixels, encoded) = maximum_image();
            fs::write(root.path().join("art.png"), &encoded).unwrap();
            let mut store = store(root.path());
            let id = store.request_png("art.png").unwrap();
            if probe == "maximum_drop" {
                // Tear the store down while the worker still holds the file,
                // the decoder and its buffers. The join is unconditional, so
                // only this watchdog bounds it.
                store.advance(WATCHDOG);
                store.advance(WATCHDOG);
                drop(store);
                return;
            }
            assert!(store.drain(WATCHDOG), "{probe} did not settle");
            assert_eq!(store.image(id).unwrap().rgba(), pixels, "{probe}");
            return;
        }
        other => panic!("unknown asset probe: {other}"),
    };
    install(root.path(), &probe, "art.png");
    let mut store = store(root.path());
    let id = store.request_png("art.png").unwrap();
    assert!(store.drain(WATCHDOG), "{probe} did not settle");
    let status = store.status(id).unwrap();
    match refusal {
        Some(code) => {
            assert_eq!(status.state, ImageState::Failed, "{probe}");
            assert_eq!(status.error.unwrap().code, code, "{probe}");
        }
        None => {
            assert_eq!(status.state, ImageState::Ready, "{probe}");
            assert_eq!(store.image(id).unwrap().rgba(), expected(&probe), "{probe}");
        }
    }
    assert!(store.service_fault().is_none(), "{probe}");
}
